local Rayfield = loadstring(game:HttpGet("https://sirius.menu/gen2"))()
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local Camera = workspace.CurrentCamera
local LocalPlayer = Players.LocalPlayer

local window = Rayfield:CreateWindow({
    name = "Cheat Menu",
        subtitle = "Built-in game feature",
            configuration = {
                    autoSave = true,
                            autoLoad = true,
                                    fileName = "CheatMenuConfig",
                                        },
                                        })

                                        -- =========================
                                        -- Общие настройки/состояние
                                        -- =========================
                                        local Settings = {
                                            AimbotEnabled = false,
                                                AimFOV = 60,
                                                    AimPart = "Head",
                                                        AimTeamCheck = true,

                                                            CamLockEnabled = false,
                                                                CamSmoothness = 0.15,

                                                                    ESPEnabled = false,
                                                                        ESPBoxes = true,
                                                                            ESPNames = true,
                                                                                ESPDistance = true,
                                                                                    ESPTeamCheck = false,
                                                                                    }

                                                                                    -- Находит ближайшую подходящую цель в пределах FOV (для аимбота и камеры)
                                                                                    local function getClosestTarget(fovLimit)
                                                                                        local closest, closestDist = nil, math.huge
                                                                                            local viewportSize = Camera.ViewportSize
                                                                                                local screenCenter = Vector2.new(viewportSize.X / 2, viewportSize.Y / 2)

                                                                                                    for _, player in ipairs(Players:GetPlayers()) do
                                                                                                            if player ~= LocalPlayer and player.Character then
                                                                                                                        local part = player.Character:FindFirstPart and player.Character:FindFirstChild(Settings.AimPart)
                                                                                                                                    if part then
                                                                                                                                                    local screenPos, onScreen = Camera:WorldToViewportPoint(part.Position)
                                                                                                                                                                    if onScreen then
                                                                                                                                                                                        local dist = (Vector2.new(screenPos.X, screenPos.Y) - screenCenter).Magnitude
                                                                                                                                                                                                            if dist < fovLimit and dist < closestDist then
                                                                                                                                                                                                                                    if not Settings.AimTeamCheck or player.Team ~= LocalPlayer.Team then
                                                                                                                                                                                                                                                                closest, closestDist = part, dist
                                                                                                                                                                                                                                                                                        end
                                                                                                                                                                                                                                                                                                            end
                                                                                                                                                                                                                                                                                                                            end
                                                                                                                                                                                                                                                                                                                                        end
                                                                                                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                                                                                                                                        return closest
                                                                                                                                                                                                                                                                                                                                                        end

                                                                                                                                                                                                                                                                                                                                                        -- =========================
                                                                                                                                                                                                                                                                                                                                                        -- Вкладка: Aimbot
                                                                                                                                                                                                                                                                                                                                                        -- =========================
                                                                                                                                                                                                                                                                                                                                                        local aimTab = window:CreateTab({ name = "Aimbot", icon = "target" })

                                                                                                                                                                                                                                                                                                                                                        aimTab:CreateSection({ name = "Наведение" })

                                                                                                                                                                                                                                                                                                                                                        aimTab:CreateToggle({
                                                                                                                                                                                                                                                                                                                                                            name = "Включить Aimbot",
                                                                                                                                                                                                                                                                                                                                                                flag = "AimbotEnabled",
                                                                                                                                                                                                                                                                                                                                                                    value = false,
                                                                                                                                                                                                                                                                                                                                                                        callback = function(value)
                                                                                                                                                                                                                                                                                                                                                                                Settings.AimbotEnabled = value
                                                                                                                                                                                                                                                                                                                                                                                    end,
                                                                                                                                                                                                                                                                                                                                                                                    })

                                                                                                                                                                                                                                                                                                                                                                                    aimTab:CreateSlider({
                                                                                                                                                                                                                                                                                                                                                                                        name = "Радиус захвата (FOV)",
                                                                                                                                                                                                                                                                                                                                                                                            range = { 10, 300 },
                                                                                                                                                                                                                                                                                                                                                                                                increment = 5,
                                                                                                                                                                                                                                                                                                                                                                                                    value = 60,
                                                                                                                                                                                                                                                                                                                                                                                                        suffix = " px",
                                                                                                                                                                                                                                                                                                                                                                                                            flag = "AimFOV",
                                                                                                                                                                                                                                                                                                                                                                                                                callback = function(value)
                                                                                                                                                                                                                                                                                                                                                                                                                        Settings.AimFOV = value
                                                                                                                                                                                                                                                                                                                                                                                                                            end,
                                                                                                                                                                                                                                                                                                                                                                                                                            })

                                                                                                                                                                                                                                                                                                                                                                                                                            aimTab:CreateDropdown({
                                                                                                                                                                                                                                                                                                                                                                                                                                name = "Точка прицеливания",
                                                                                                                                                                                                                                                                                                                                                                                                                                    options = { "Head", "HumanoidRootPart", "UpperTorso" },
                                                                                                                                                                                                                                                                                                                                                                                                                                        value = "Head",
                                                                                                                                                                                                                                                                                                                                                                                                                                            flag = "AimPart",
                                                                                                                                                                                                                                                                                                                                                                                                                                                callback = function(selected)
                                                                                                                                                                                                                                                                                                                                                                                                                                                        Settings.AimPart = selected
                                                                                                                                                                                                                                                                                                                                                                                                                                                            end,
                                                                                                                                                                                                                                                                                                                                                                                                                                                            })

                                                                                                                                                                                                                                                                                                                                                                                                                                                            aimTab:CreateToggle({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                name = "Игнорировать свою команду",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    flag = "AimTeamCheck",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        value = true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            callback = function(value)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Settings.AimTeamCheck = value
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        end,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        })

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        -- Здесь вы подключаете свою систему стрельбы:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        -- получаем цель, а дальше сами решаете, как её использовать
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        -- (например, передать в RemoteEvent вашего оружия)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        RunService.RenderStepped:Connect(function()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if Settings.AimbotEnabled then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    local target = getClosestTarget(Settings.AimFOV)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if target then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        -- ПРИМЕР: подставьте вызов вашей системы стрельбы/прицела
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    -- MyWeaponSystem:SetAimTarget(target)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                end)

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                -- =========================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                -- Вкладка: Camera Lock (бот, наводящий камеру)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                -- =========================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                local camTab = window:CreateTab({ name = "Camera Lock", icon = "camera" })

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                camTab:CreateSection({ name = "Автослежение камеры" })

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                camTab:CreateToggle({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    name = "Включить наведение камеры",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        flag = "CamLockEnabled",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            value = false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                callback = function(value)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Settings.CamLockEnabled = value
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            end,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            })

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            camTab:CreateSlider({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                name = "Плавность",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    range = { 0, 1 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        increment = 0.05,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            value = 0.15,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                flag = "CamSmoothness",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    callback = function(value)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Settings.CamSmoothness = value
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                end,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                })

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                RunService.RenderStepped:Connect(function()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if Settings.CamLockEnabled then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            local target = getClosestTarget(Settings.AimFOV)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if target then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                local currentCFrame = Camera.CFrame
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            local targetCFrame = CFrame.new(currentCFrame.Position, target.Position)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Camera.CFrame = currentCFrame:Lerp(targetCFrame, Settings.CamSmoothness)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    end)

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    -- =========================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    -- Вкладка: ESP
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    -- =========================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    local espTab = window:CreateTab({ name = "ESP", icon = "eye" })

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    espTab:CreateSection({ name = "Отображение игроков" })

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    espTab:CreateToggle({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        name = "Включить ESP",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            flag = "ESPEnabled",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                value = false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    callback = function(value)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Settings.ESPEnabled = value
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    for _, player in ipairs(Players:GetPlayers()) do
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if player.Character then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                local highlight = player.Character:FindFirstChild("ESP_Highlight")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if highlight then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    highlight.Enabled = value
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            end,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            })

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            espTab:CreateToggle({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                name = "Имена игроков",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    flag = "ESPNames",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        value = true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            callback = function(value)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Settings.ESPNames = value
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        end,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        })

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        espTab:CreateToggle({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            name = "Показывать дистанцию",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                flag = "ESPDistance",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    value = true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        callback = function(value)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Settings.ESPDistance = value
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    end,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    })

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    -- Создаёт Highlight + BillboardGui с именем/дистанцией для персонажа
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    local function applyESP(character, player)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if character:FindFirstChild("ESP_Highlight") then return end

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            local highlight = Instance.new("Highlight")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                highlight.Name = "ESP_Highlight"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    highlight.FillTransparency = 0.5
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        highlight.OutlineTransparency = 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            highlight.Enabled = Settings.ESPEnabled
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                highlight.Parent = character

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    local head = character:FindFirstChild("Head")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if head then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                local billboard = Instance.new("BillboardGui")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        billboard.Name = "ESP_Label"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                billboard.Size = UDim2.new(0, 150, 0, 40)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        billboard.StudsOffset = Vector3.new(0, 2, 0)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                billboard.AlwaysOnTop = true
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        billboard.Parent = head

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                local label = Instance.new("TextLabel")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        label.Size = UDim2.new(1, 0, 1, 0)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                label.BackgroundTransparency = 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        label.TextColor3 = Color3.new(1, 1, 1)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                label.TextStrokeTransparency = 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        label.Font = Enum.Font.GothamBold
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                label.TextSize = 14
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        label.Parent = billboard

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                RunService.RenderStepped:Connect(function()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if not Settings.ESPEnabled or not head.Parent then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            label.Visible = false
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    label.Visible = true

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                local text = player.Name
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if Settings.ESPDistance then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            local dist = (Camera.CFrame.Position - head.Position).Magnitude
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            text = text .. string.format(" [%dm]", dist)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if not Settings.ESPNames then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    text = Settings.ESPDistance and string.format("[%dm]", (Camera.CFrame.Position - head.Position).Magnitude) or ""
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            label.Text = text
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    end)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        end

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        for _, player in ipairs(Players:GetPlayers()) do
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if player ~= LocalPlayer and player.Character then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    applyESP(player.Character, player)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            player.CharacterAdded:Connect(function(character)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if player ~= LocalPlayer then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                applyESP(character, player)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            end)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            end

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Players.PlayerAdded:Connect(function(player)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                player.CharacterAdded:Connect(function(character)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        applyESP(character, player)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            end)
